import{_ as a,o,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const t="/assets/image%20(2)%20(1)%20(1)%20(1)%20(1).Bzc5fK1L.png",r="/assets/image%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).BohkMEIy.png",s="/assets/image%20(2)%20(1)%20(1)%20(1)%20(1)%20(1).Bvnvoxfm.png",d="/assets/image%20(3)%20(1)%20(1)%20(1).CvWbnFlV.png",k=JSON.parse('{"title":"Dhan(Sandbox)","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/dhan-sandbox.md","filePath":"connect-brokers/brokers/dhan-sandbox.md"}'),l={name:"connect-brokers/brokers/dhan-sandbox.md"};function c(h,e,p,g,u,b){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="dhan-sandbox" tabindex="-1">Dhan(Sandbox) <a class="header-anchor" href="#dhan-sandbox" aria-label="Permalink to &quot;Dhan(Sandbox)&quot;">​</a></h1><p><strong>What is Dhan SandBox API?</strong></p><p>Dhan SandBox API is a simulated testing environment designed for developers and traders to experiment with Dhan’s trading and market data APIs without needing a live brokerage account or actual capital. It replicates the real trading environment but ensures zero risk by not executing trades on the actual exchange. It is ideal for testing integrations, validating order logic, and experimenting with strategies.</p><hr><p><strong>Who Should Integrate Dhan SandBox API with Tradeboard?</strong></p><p>Tradeboard is an open-source algo trading automation framework that connects with platforms like TradingView, Amibroker, and custom dashboards. Integrating Dhan’s SandBox API with Tradeboard is highly recommended for:</p><ul><li><strong>Algo Developers</strong> building broker connectors.</li><li><strong>Traders</strong> who want to simulate real-time automated strategies before going live.</li><li><strong>Educators and Trainers</strong> who want a safe demo environment.</li><li><strong>Early-stage Fintech Builders</strong> exploring trading APIs.</li><li><strong>QA and Support Teams</strong> needing to replicate live bugs or behaviors in a controlled setup.</li></ul><hr><p><strong>Step-by-Step: How to Get Started with Dhan SandBox API</strong></p><p>Here’s how to register, access tokens, and start testing with Tradeboard:</p><h4 id="_1-visit-dhanhq-devportal" tabindex="-1">1. <strong>Visit DhanHQ DevPortal</strong> <a class="header-anchor" href="#_1-visit-dhanhq-devportal" aria-label="Permalink to &quot;1. **Visit DhanHQ DevPortal**&quot;">​</a></h4><p>You’ll land on a login screen where you can enter your email or mobile number.</p><figure><img src="'+t+'" alt=""><figcaption></figcaption></figure><hr><h4 id="_2-register-if-new" tabindex="-1">2. <strong>Register (if new)</strong> <a class="header-anchor" href="#_2-register-if-new" aria-label="Permalink to &quot;2. **Register (if new)**&quot;">​</a></h4><p>If you’re a new user, click to register. Provide:</p><ul><li>Email ID</li><li>Mobile Number</li><li>Your Name</li></ul><p>Proceed to the next step.</p><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><hr><h4 id="_3-otp-verification" tabindex="-1">3. <strong>OTP Verification</strong> <a class="header-anchor" href="#_3-otp-verification" aria-label="Permalink to &quot;3. **OTP Verification**&quot;">​</a></h4><p>You will receive two OTPs:</p><ul><li>One on your <strong>email</strong></li><li>One on your <strong>mobile</strong></li></ul><p>Enter both to complete verification.</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><hr><h4 id="_4-access-your-sandbox-token-and-client-id" tabindex="-1">4. <strong>Access Your Sandbox Token and Client ID</strong> <a class="header-anchor" href="#_4-access-your-sandbox-token-and-client-id" aria-label="Permalink to &quot;4. **Access Your Sandbox Token and Client ID**&quot;">​</a></h4><p>Once inside, go to the <strong>Sandbox</strong> tab. You’ll see:</p><ul><li>Application Name (e.g., <code>tradeboard</code>)</li><li><strong>Access Token</strong> (JWT for authorization)</li><li><strong>Client ID</strong> (unique to your application)</li><li>API Playground and documentation links</li></ul><figure><img src="'+d+`" alt=""><figcaption></figcaption></figure><p>These credentials are what you will use inside Tradeboard’s configuration or <code>.env</code> file to test trading orders programmatically.</p><hr><h4 id="retrieve-api-credentials" tabindex="-1">Retrieve API Credentials <a class="header-anchor" href="#retrieve-api-credentials" aria-label="Permalink to &quot;Retrieve API Credentials&quot;">​</a></h4><p>Once you&#39;ve successfully logged into the DhanHQ DevPortal and created your sandbox application:</p><ol><li><strong>Copy the Client ID</strong><ul><li>This is your <code>BROKER_API_KEY</code></li><li>It uniquely identifies your application (e.g., <code>2505178942</code>)</li></ul></li><li><strong>Copy the Access Token</strong><ul><li>This is your <code>BROKER_API_SECRET</code></li></ul></li></ol><p>It acts like a password (JWT format) to authenticate your API requests.</p><h4 id="configuration-for-tradeboard" tabindex="-1">Configuration for Tradeboard <a class="header-anchor" href="#configuration-for-tradeboard" aria-label="Permalink to &quot;Configuration for Tradeboard&quot;">​</a></h4><p>Inside your Tradeboard project (or any backend using Dhan APIs), create or update the <code>.env</code> file with the following keys:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your_dhan_sandbox_clientid_here&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your_dhan_sandbox_token_here&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">REDIRECT_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/dhan_sandbox/callback&#39;</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The broker code is <code>dhan_sandbox</code>, with an underscore. It is a separate plugin from <a href="./dhan.html">Dhan</a>, so switching between live and sandbox means changing <code>REDIRECT_URL</code> as well as the credentials.</p><p><code>BROKER_API_KEY</code> accepts either a bare client ID, as shown above, or the composite <code>client_id:::api_key</code> form used by the live Dhan plugin. Clicking <strong>Connect</strong> does not open a Dhan login page: Tradeboard authenticates with the access token in <code>BROKER_API_SECRET</code> directly.</p></div><p><strong>Summary: Why It Matters for Tradeboard</strong></p><p>Integrating Dhan SandBox with Tradeboard means:</p><ul><li>Safer testing for order placement, cancellation, and position handling.</li><li>No compliance delay since no KYC is needed.</li><li>Faster debugging and integration turnaround.</li><li>Enables workshops, testing, and community support for algo development.</li></ul><p>By setting up your sandbox environment with Dhan and Tradeboard, you accelerate your readiness for live algorithmic trading while ensuring a risk-free development experience.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/dhan_sandbox/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,47)])])}const f=a(l,[["render",c]]);export{k as __pageData,f as default};
